window.docContents[156].resolve({"/versions/#versions-hosting":{"contents":"The site is a static GitHub Pages project site. It uses no cookies, accounts or analytics. Search and the page table of contents use Verso's JavaScript, and pages load one library from the jsDelivr CDN (see the credits); every explanation, link and the rule catalogue work without it. A deployment can lag main while checks run or after they fail; each page states the commit it was built from. Every published snapshot is kept, so the site grows with each deployment; the build refuses an artifact larger than 900 MB, below GitHub Pages' 1 GB limit on a published site. Removing snapshots would change what their routes mean and needs a separate decision.\n\n\n","context":"Regula rule reference\u0009Versions and evidence","header":"Hosting limits","id":"/versions/#versions-hosting"}});